{% if has_search_disposal == false %}
    <link rel="stylesheet" href="{{ asset('assets/css/stock-history.css', 'admin') }}">
{% else %}
    <link rel="stylesheet" href="{{ asset('assets/css/stock-history-disposal.css', 'admin') }}">
{% endif %}

// disposal_search 欠品検索
$DisposalTypeIds = $this->stockChangeTypeDetailRepository->getQueryBuilderByStockChangeTypeIds(
    [MtbStockChangeType::DISPOSAL]
)->getQuery()->getResult();
if (isset($searchData['disposal_search']) && StringUtil::isNotBlank($searchData['disposal_search'])) {
    $qb
        ->andWhere($qb->expr()->in('sh.StockChangeTypeDetail', ':stock_change_type_detail'))
        ->setParameter('stock_change_type_detail', $DisposalTypeIds);
} elseif (!empty($DisposalTypeIds)) {
    $qb
        ->andWhere($qb->expr()->notIn('sh.StockChangeTypeDetail', ':disposal_change_type_detail'))
        ->setParameter('disposal_change_type_detail', $DisposalTypeIds);
}
